import{c as a,Q as t,j as n,m as o}from"./chunks/framework.g_l1frA7.js";const u=JSON.parse('{"title":"Plans & Actions","description":"","frontmatter":{},"headers":[],"relativePath":"copilot/plans.md","filePath":"copilot/plans.md","lastUpdated":null}'),i={name:"copilot/plans.md"};function s(r,e,l,d,c,p){return t(),n("div",null,[...e[0]||(e[0]=[o('<h1 id="plans-actions" tabindex="-1">Plans &amp; Actions <a class="header-anchor" href="#plans-actions" aria-label="Permalink to &quot;Plans &amp; Actions&quot;">​</a></h1><p>Plans are the Copilot’s proposal before it does anything. Actions are the steps it takes once you approve.</p><h2 id="plans" tabindex="-1">Plans <a class="header-anchor" href="#plans" aria-label="Permalink to &quot;Plans&quot;">​</a></h2><p>A plan (<code>planner::PlanResult</code>) contains:</p><ul><li><strong>Title</strong> — one line, ≤80 chars, what the plan achieves.</li><li><strong>Steps</strong> — ordered, each with a kind from <code>ACTION_KINDS</code> and arguments.</li><li><strong>Confidence</strong> — clamped 0–1.</li><li><strong>Provider + model</strong> — for transparency.</li></ul><p>Plans are persisted immediately — the UI can render them even if streaming is interrupted.</p><h2 id="agent-memory-and-clarifications" tabindex="-1">Agent memory and clarifications <a class="header-anchor" href="#agent-memory-and-clarifications" aria-label="Permalink to &quot;Agent memory and clarifications&quot;">​</a></h2><ul><li><strong>Memory</strong> (<code>repos/agent_memory</code>) — small, reviewable items the Copilot stores (“User wants groceries at $600”). Surfaced at <strong>Insights → Memory</strong> and fed into context only when relevant. Delete any you disagree with.</li><li><strong>Clarifications</strong> — when a question is ambiguous (which account? which month?), the Copilot asks via the <code>clarifications</code> state and pauses planning until answered.</li></ul><h2 id="actions-and-bundles" tabindex="-1">Actions and bundles <a class="header-anchor" href="#actions-and-bundles" aria-label="Permalink to &quot;Actions and bundles&quot;">​</a></h2><p>Post-planning, approved actions execute via <code>executor</code> through <code>ApiState</code>. Each step reports running / complete / error. The Copilot then narrates outcomes with figure citations.</p><p><strong>Action bundles</strong> — pending multi-step automations that need your review — appear in the sidebar badge, the Copilot inbox, and <strong>Insights</strong>. They survive restarts and are listed via <code>actionBundleKeys</code> queries.</p><h2 id="guardrails" tabindex="-1">Guardrails <a class="header-anchor" href="#guardrails" aria-label="Permalink to &quot;Guardrails&quot;">​</a></h2><ul><li>Steps are allow-listed; the dispatcher rejects unknown kinds.</li><li>Navigation links the model emits are validated against <code>APP_ROUTES</code> in both frontend and Rust (<code>routes.rs</code>) — the model cannot link to a screen that does not exist.</li><li>Tool calls are typed and envelope-wrapped (<code>Result&lt;T, AppError&gt;</code>); failures surface as error parts, not silent skips.</li></ul><p>See also: <a href="/FinSight/copilot/memory">Agent Memory</a>, <a href="/FinSight/copilot/scenarios">Scenarios</a>.</p>',14)])])}const m=a(i,[["render",s]]);export{u as __pageData,m as default};
